// DASH-006 — Citrix Protocol Experience Summary
// Source: SPL-D006-0114
let StartTime = _startTime;
let EndTime = _endTime;
let UserFilter = tolower(tostring(_user));
let HostFilter = tostring(_host);
let SessionFilter = tostring(_session);
let VirtualChannelFilter = tostring(_virtualChannel);
let DurationHours = toreal(datetime_diff('second', EndTime, StartTime)) / 3600.0;
let SessionVolumes =
    CitrixSession_VirtualChannelDetail
    | where Timestamp between (StartTime .. EndTime)
    | where isempty(UserFilter) or tolower(SessionUser) =~ UserFilter
    | where isempty(HostFilter) or Host =~ HostFilter
    | where isempty(SessionFilter) or tostring(SessionGUID) == SessionFilter
    | where isempty(VirtualChannelFilter) or VirtualChannelVendorName =~ VirtualChannelFilter
    | extend DataVolumeMB=coalesce(VirtualChannelDataVolumeInputMB,0.0)+coalesce(VirtualChannelDataVolumeOutputMB,0.0)
    | summarize SessionDataVolumeMB=sum(DataVolumeMB), User=take_any(SessionUser), Host=take_any(Host) by SessionGUID;
let UniqueSessions = toscalar(SessionVolumes | summarize dcount(SessionGUID));
let UniqueUsers = toscalar(SessionVolumes | summarize dcountif(User, isnotempty(User)));
let UniqueHosts = toscalar(SessionVolumes | summarize dcountif(Host, isnotempty(Host)));
let AvgSessionDataVolumeMB = toscalar(SessionVolumes | summarize avg(SessionDataVolumeMB));
let AvgIcaLatencyMs = toscalar(
    Session_SessionDetail
    | where Timestamp between (StartTime .. EndTime)
    | where isempty(UserFilter) or tolower(SessionUser) =~ UserFilter
    | where isempty(HostFilter) or Host =~ HostFilter
    | where isempty(SessionFilter) or tostring(SessionGUID) == SessionFilter
    | where SessionProtocol =~ "ICA"
    | summarize round(avg(SessionRpLatencyMs2),1)
);
let AvgIcaRoundTripTimeMs = toscalar(
    Session_SessionDetail
    | where Timestamp between (StartTime .. EndTime)
    | where isempty(UserFilter) or tolower(SessionUser) =~ UserFilter
    | where isempty(HostFilter) or Host =~ HostFilter
    | where isempty(SessionFilter) or tostring(SessionGUID) == SessionFilter
    | where SessionProtocol =~ "ICA"
    | summarize round(avg(toreal(SessionRoundTripTimeMs)),1)
);
let VirtualChannels =
    CitrixSession_VirtualChannelDetail
    | where Timestamp between (StartTime .. EndTime)
    | where isempty(UserFilter) or tolower(SessionUser) =~ UserFilter
    | where isempty(HostFilter) or Host =~ HostFilter
    | where isempty(SessionFilter) or tostring(SessionGUID) == SessionFilter
    | where isempty(VirtualChannelFilter) or VirtualChannelVendorName =~ VirtualChannelFilter
    | extend DataVolumeMB=coalesce(VirtualChannelDataVolumeInputMB,0.0)+coalesce(VirtualChannelDataVolumeOutputMB,0.0)
    | where isnotempty(VirtualChannelVendorName)
    | summarize DataVolumeMB=sum(DataVolumeMB) by VirtualChannel=VirtualChannelVendorName;
let VirtualChannelsInUse = toscalar(VirtualChannels | summarize countif(DataVolumeMB > 0));
let VirtualChannelsTotal = toscalar(VirtualChannels | summarize count());
union
    (print Metric="Unique Sessions", MetricValue=toreal(UniqueSessions)),
    (print Metric="Unique Users", MetricValue=toreal(UniqueUsers)),
    (print Metric="Unique Hosts", MetricValue=toreal(UniqueHosts)),
    (print Metric="Avg Session Data MB/hour", MetricValue=iff(DurationHours > 0, round(toreal(AvgSessionDataVolumeMB) / DurationHours, 1), real(null))),
    (print Metric="Avg ICA Latency ms", MetricValue=toreal(AvgIcaLatencyMs)),
    (print Metric="Avg ICA RTT ms", MetricValue=toreal(AvgIcaRoundTripTimeMs)),
    (print Metric="Virtual Channels In Use", MetricValue=toreal(VirtualChannelsInUse)),
    (print Metric="Virtual Channels Total", MetricValue=toreal(VirtualChannelsTotal))

// DASH-006 — Network and Session Reliability Settings
// Source: SPL-D006-0003
let StartTime = _startTime;
let EndTime = _endTime;
let UserFilter = tolower(tostring(_user));
let HostFilter = tostring(_host);
let SessionFilter = tostring(_session);
let ConfigLatest =
    CitrixSession_SessionConfig
    | where Timestamp between (StartTime .. EndTime)
    | where isnotempty(tostring(SessionGUID))
    | where isempty(UserFilter) or tolower(SessionUser) =~ UserFilter
    | where isempty(HostFilter) or Host =~ HostFilter
    | where isempty(SessionFilter) or tostring(SessionGUID) == SessionFilter
    | summarize arg_max(Timestamp, *) by SessionGUID
    | extend User = tolower(SessionUser);
union
    (ConfigLatest | project SessionGUID, User, Host, Category="Network", Setting="Connected via", Value=iff(isempty(NetworkConnectedVia), "Unknown", NetworkConnectedVia)),
    (ConfigLatest | project SessionGUID, User, Host, Category="Network", Setting="EDT MTU", Value=iff(isnull(NetworkEdtMtu), "Unknown", tostring(NetworkEdtMtu))),
    (ConfigLatest | project SessionGUID, User, Host, Category="Reliability", Setting="Session reliability allowed", Value=iff(isnull(NetworkPolicyAcceptSessionReliabilityConnections), "Unknown", tostring(NetworkPolicyAcceptSessionReliabilityConnections))),
    (ConfigLatest | project SessionGUID, User, Host, Category="Reliability", Setting="Session reliability port", Value=iff(isnull(NetworkPolicySessionReliabilityPort), "Unknown", tostring(NetworkPolicySessionReliabilityPort))),
    (ConfigLatest | project SessionGUID, User, Host, Category="Reliability", Setting="Session reliability timeout (s)", Value=iff(isnull(NetworkPolicySessionReliabilityTimeout), "Unknown", tostring(NetworkPolicySessionReliabilityTimeout))),
    (ConfigLatest | project SessionGUID, User, Host, Category="ICA", Setting="ICA listener port", Value=iff(isnull(NetworkPolicyICAListenerPortNumber), "Unknown", tostring(NetworkPolicyICAListenerPortNumber)))
| summarize Sessions=dcount(SessionGUID), Users=dcountif(User, isnotempty(User)), Hosts=dcountif(Host, isnotempty(Host)) by Category, Setting, Value
| order by Category asc, Setting asc, Sessions desc

// DASH-006 — ICA Latency and Round-Trip Time Over Time
// Source: SPL-D006-0120
let StartTime = _startTime;
let EndTime = _endTime;
let UserFilter = tolower(tostring(_user));
let HostFilter = tostring(_host);
let SessionFilter = tostring(_session);
let TimeBin = 15m;
Session_SessionDetail
| where Timestamp between (StartTime .. EndTime)
| where SessionProtocol =~ "ICA"
| where isempty(UserFilter) or tolower(SessionUser) =~ UserFilter
| where isempty(HostFilter) or Host =~ HostFilter
| where isempty(SessionFilter) or tostring(SessionGUID) == SessionFilter
| summarize
    AvgICALatencyMs = round(avg(SessionRpLatencyMs2), 1),
    P95ICALatencyMs = round(percentile(SessionRpLatencyMs2, 95), 1),
    AvgICARoundTripTimeMs = round(avg(toreal(SessionRoundTripTimeMs)), 1),
    P95ICARoundTripTimeMs = round(percentile(toreal(SessionRoundTripTimeMs), 95), 1),
    Sessions = dcount(SessionGUID)
    by TimeBucket = bin(Timestamp, TimeBin)
| order by TimeBucket asc

// DASH-006 — TCP Send Packet Loss Over Time
// Source: SPL-D006-0139
let StartTime = _startTime;
let EndTime = _endTime;
let UserFilter = tolower(tostring(_user));
let HostFilter = tostring(_host);
let TargetFilter = tostring(_target);
let TimeBin = 15m;
Process_NetworkTargetPerformance
| where Timestamp between (StartTime .. EndTime)
| extend Target = iff(isnotempty(NetTargetRemoteName), NetTargetRemoteName, tostring(NetTargetRemoteAddress))
| where isempty(UserFilter) or tolower(ProcUser) =~ UserFilter
| where isempty(HostFilter) or Host =~ HostFilter
| where isempty(TargetFilter) or Target =~ TargetFilter
| where NetTargetProtocols =~ "TCP"
| summarize Retransmits=sum(NetTargetRetransmitCount), Sends=sum(NetTargetSendCount) by TimeBucket=bin(Timestamp, TimeBin)
| extend PacketLossPercent=iff(Retransmits + Sends > 0, round(100.0 * Retransmits / (Retransmits + Sends),2), real(null))
| project TimeBucket, PacketLossPercent, Retransmits, Sends
| order by TimeBucket asc

// DASH-006 — Virtual Channel Usage Summary
// Source: SPL-D006-0121
let StartTime = _startTime;
let EndTime = _endTime;
let UserFilter = tolower(tostring(_user));
let HostFilter = tostring(_host);
let SessionFilter = tostring(_session);
let VirtualChannelFilter = tostring(_virtualChannel);
CitrixSession_VirtualChannelDetail
| where Timestamp between (StartTime .. EndTime)
    | where isempty(UserFilter) or tolower(SessionUser) =~ UserFilter
    | where isempty(HostFilter) or Host =~ HostFilter
    | where isempty(SessionFilter) or tostring(SessionGUID) == SessionFilter
    | where isempty(VirtualChannelFilter) or VirtualChannelVendorName =~ VirtualChannelFilter
| where isnotempty(VirtualChannelVendorName)
| extend DataVolumeMB=coalesce(VirtualChannelDataVolumeInputMB,0.0)+coalesce(VirtualChannelDataVolumeOutputMB,0.0)
| summarize TotalDataVolumeMB=sum(DataVolumeMB) by VirtualChannel=VirtualChannelVendorName
| extend UsageStatus=iff(TotalDataVolumeMB > 0, "In use", "Not in use")
| summarize ChannelCount=count() by UsageStatus
| order by UsageStatus asc

// DASH-006 — Virtual Channel Data Volume by Channel
// Source: SPL-D006-0122
let StartTime = _startTime;
let EndTime = _endTime;
let UserFilter = tolower(tostring(_user));
let HostFilter = tostring(_host);
let SessionFilter = tostring(_session);
let VirtualChannelFilter = tostring(_virtualChannel);
CitrixSession_VirtualChannelDetail
| where Timestamp between (StartTime .. EndTime)
    | where isempty(UserFilter) or tolower(SessionUser) =~ UserFilter
    | where isempty(HostFilter) or Host =~ HostFilter
    | where isempty(SessionFilter) or tostring(SessionGUID) == SessionFilter
    | where isempty(VirtualChannelFilter) or VirtualChannelVendorName =~ VirtualChannelFilter
| where isnotempty(VirtualChannelVendorName)
| summarize
    InputDataVolumeMB=round(sum(VirtualChannelDataVolumeInputMB),2),
    OutputDataVolumeMB=round(sum(VirtualChannelDataVolumeOutputMB),2),
    Sessions=dcount(SessionGUID),
    Users=dcountif(SessionUser,isnotempty(SessionUser)),
    Hosts=dcountif(Host,isnotempty(Host))
    by VirtualChannel=VirtualChannelVendorName
| extend TotalDataVolumeMB=round(InputDataVolumeMB + OutputDataVolumeMB,2)
| project VirtualChannel, TotalDataVolumeMB, InputDataVolumeMB, OutputDataVolumeMB, Sessions, Users, Hosts
| order by TotalDataVolumeMB desc

// DASH-006 — Session Virtual Channel Matrix
// Source: SPL-D006-0124
let StartTime = _startTime;
let EndTime = _endTime;
let UserFilter = tolower(tostring(_user));
let HostFilter = tostring(_host);
let SessionFilter = tostring(_session);
let VirtualChannelFilter = tostring(_virtualChannel);
let TimeBin = 1h;
let VirtualChannelBase =
    CitrixSession_VirtualChannelDetail
    | where Timestamp between (StartTime .. EndTime)
    | where isempty(UserFilter) or tolower(SessionUser) =~ UserFilter
    | where isempty(HostFilter) or Host =~ HostFilter
    | where isempty(SessionFilter) or tostring(SessionGUID) == SessionFilter
    | where isempty(VirtualChannelFilter) or VirtualChannelVendorName =~ VirtualChannelFilter
    | where isnotempty(VirtualChannelVendorName)
    | extend VirtualChannel=VirtualChannelVendorName, DataVolumeMB=coalesce(VirtualChannelDataVolumeInputMB,0.0)+coalesce(VirtualChannelDataVolumeOutputMB,0.0);
let ChannelMatrix =
    VirtualChannelBase
    | summarize ChannelDataVolumeMB=sum(DataVolumeMB) by SessionGUID, VirtualChannel
    | summarize VirtualChannelVolumesMB=make_bag(bag_pack(VirtualChannel, round(ChannelDataVolumeMB,1))) by SessionGUID;
let SessionVolume =
    VirtualChannelBase
    | summarize TotalDataVolumeMB=round(sum(DataVolumeMB),1) by SessionGUID;
let AverageVolume =
    VirtualChannelBase
    | summarize BinDataVolumeMB=sum(DataVolumeMB) by SessionGUID, TimeBucket=bin(Timestamp,TimeBin)
    | summarize AvgDataVolumeMB=round(avg(BinDataVolumeMB),1) by SessionGUID;
let SessionDetails =
    Session_SessionDetail
    | where Timestamp between (StartTime .. EndTime)
    | where isempty(UserFilter) or tolower(SessionUser) =~ UserFilter
    | where isempty(HostFilter) or Host =~ HostFilter
    | where isempty(SessionFilter) or tostring(SessionGUID) == SessionFilter
    | where isnotempty(tostring(SessionGUID))
    | summarize arg_max(Timestamp, SessionUser, Host, SessionLogonTime, SessionConnectionState, CtxHDXDirectStatus) by SessionGUID
    | project SessionGUID, User=SessionUser, Host, LogonTime=SessionLogonTime, LastSeen=Timestamp, LastState=SessionConnectionState, HDXDirectStatus=CtxHDXDirectStatus;
ChannelMatrix
| join kind=leftouter SessionVolume on SessionGUID
| join kind=leftouter AverageVolume on SessionGUID
| join kind=leftouter SessionDetails on SessionGUID
| project User, Host, LogonTime, LastSeen, LastState, AvgDataVolumeMB, TotalDataVolumeMB, HDXDirectStatus, SessionGUID, VirtualChannelVolumesMB
| order by LastSeen desc

let StartTime = _startTime;
let EndTime = _endTime;
let UserFilter = tolower(tostring(_user));
let HostFilter = tostring(_host);
let SessionFilter = tostring(_session);
CitrixSession_VirtualChannelDetail
| where Timestamp between (StartTime .. EndTime)
| where isnotempty(VirtualChannelVendorName)
| where isempty(UserFilter) or tolower(SessionUser) =~ UserFilter
| where isempty(HostFilter) or Host =~ HostFilter
| where isempty(SessionFilter) or tostring(SessionGUID) == SessionFilter
| summarize Sessions=dcount(SessionGUID), DataVolumeMB=round(sum(VirtualChannelDataVolumeInputMB)+sum(VirtualChannelDataVolumeOutputMB),1) by VirtualChannel=VirtualChannelVendorName
| extend Value=VirtualChannel, Label=strcat(VirtualChannel, " (", tostring(Sessions), " sessions)")
| project Value, Label
| order by Label asc
